        impl pe :: ImageSectionHeader { # [doc = " Return the offset and size of the section in a PE file."] # [doc = ""] # [doc = " The size of the range will be the minimum of the file size and virtual size."] pub fn pe_file_range (& self) -> (u32 , u32) { let offset = self . pointer_to_raw_data . get (LE) ; let size = cmp :: min (self . virtual_size . get (LE) , self . size_of_raw_data . get (LE)) ; (offset , size) } # [doc = " Return the file offset of the given virtual address, and the remaining size up"] # [doc = " to the end of the section."] # [doc = ""] # [doc = " Returns `None` if the section does not contain the address."] pub fn pe_file_range_at (& self , va : u32) -> Option < (u32 , u32) > { let section_va = self . virtual_address . get (LE) ; let offset = va . checked_sub (section_va) ? ; let (section_offset , section_size) = self . pe_file_range () ; if offset < section_size { Some ((section_offset . checked_add (offset) ? , section_size - offset)) } else { None } } # [doc = " Return the virtual address and size of the section."] pub fn pe_address_range (& self) -> (u32 , u32) { (self . virtual_address . get (LE) , self . virtual_size . get (LE)) } # [doc = " Return the section data in a PE file."] # [doc = ""] # [doc = " The length of the data will be the minimum of the file size and virtual size."] pub fn pe_data < 'data , R : ReadRef < 'data > > (& self , data : R) -> Result < & 'data [u8] > { let (offset , size) = self . pe_file_range () ; data . read_bytes_at (offset . into () , size . into ()) . read_error ("Invalid PE section offset or size") } # [doc = " Return the data starting at the given virtual address, up to the end of the"] # [doc = " section."] # [doc = ""] # [doc = " Ignores sections with invalid data."] # [doc = ""] # [doc = " Returns `None` if the section does not contain the address."] pub fn pe_data_at < 'data , R : ReadRef < 'data > > (& self , data : R , va : u32) -> Option < & 'data [u8] > { let (offset , size) = self . pe_file_range_at (va) ? ; data . read_bytes_at (offset . into () , size . into ()) . ok () } # [doc = " Tests whether a given RVA is part of this section"] pub fn contains_rva (& self , va : u32) -> bool { let section_va = self . virtual_address . get (LE) ; match va . checked_sub (section_va) { None => false , Some (offset) => { offset < self . virtual_size . get (LE) } } } # [doc = " Return the section data if it contains the given virtual address."] # [doc = ""] # [doc = " Also returns the virtual address of that section."] # [doc = ""] # [doc = " Ignores sections with invalid data."] pub fn pe_data_containing < 'data , R : ReadRef < 'data > > (& self , data : R , va : u32 ,) -> Option < (& 'data [u8] , u32) > { let section_va = self . virtual_address . get (LE) ; let offset = va . checked_sub (section_va) ? ; let (section_offset , section_size) = self . pe_file_range () ; if offset < section_size { let section_data = data . read_bytes_at (section_offset . into () , section_size . into ()) . ok () ? ; Some ((section_data , section_va)) } else { None } } }
